"""Management-first Project Monitor UI: work + payment plan/fact on one timeline."""

# main_legacy imports developaid_monitor first and this page second. Installing
# the aggregation here keeps all arithmetic server-side: the page only renders
# the already-built management hierarchy.
import developaid_monitor_manager as _manager
_manager.install()

MONITOR_PAGE = r"""<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><title>DevelopAid — Project Monitor</title>
<style>
*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;margin:0;background:#f5f6f7;color:#17191c}header{background:#111820;color:#fff;padding:16px 22px;display:flex;gap:12px;align-items:baseline}header h1{font-size:18px;margin:0}.ver{font-size:11px;color:#89939e}main{max-width:1440px;margin:auto;padding:18px}.card{background:#fff;border:1px solid #e0e4e8;border-radius:10px;padding:15px 17px;margin-bottom:14px}h2{font-size:14px;margin:0 0 10px}.muted{font-size:12px;color:#68727d}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:9px}.kpi{border:1px solid #e7e9ec;border-radius:8px;padding:10px}.kpi .l{font-size:11px;color:#68727d}.kpi .n{font-size:18px;font-weight:650;margin-top:2px}.bad{color:#b42318}.good{color:#067647}input,button{font:inherit;border:1px solid #c8cdd3;border-radius:7px;padding:7px 9px;background:#fff}button{cursor:pointer}button.dark{background:#111820;color:#fff;border-color:#111820}input[type=file]{padding:5px;font-size:12px}.msg{font-size:12px;margin-top:7px;min-height:15px}.err{color:#b42318}.ok{color:#067647}.setup{border-left:3px solid #6b7785}.weekly{border-left:3px solid #111820}.pill{font-size:11px;padding:2px 8px;border-radius:999px;background:#eef1f4;margin-left:5px}.section-note{margin-top:-5px;margin-bottom:10px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border-bottom:1px solid #edf0f2;padding:6px 7px;text-align:right;white-space:nowrap}th{font-size:11px;color:#68727d;font-weight:550}th:first-child,td:first-child{text-align:left}.status-bad{color:#b42318;font-weight:650}.status-good{color:#067647;font-weight:650}.status-muted{color:#68727d}
.legend{display:flex;gap:14px;flex-wrap:wrap;margin:6px 0 12px;font-size:11px;color:#68727d}.lg{display:inline-flex;gap:5px;align-items:center}.sw{width:18px;height:7px;border-radius:2px;background:#b9c2cc}.sw.fact{background:#315d85}.sw.payplan{height:12px;width:5px;background:#c7cdd3}.sw.payfact{height:12px;width:5px;background:#242e38}.sw.forecast{height:13px;width:2px;background:#b42318}
.gantt-wrap{min-width:1030px}.g-axis{display:grid;grid-template-columns:350px 1fr 250px;align-items:end;border-bottom:1px solid #dfe3e7;padding-bottom:6px;margin-bottom:2px}.axis-time{position:relative;height:28px}.tick{position:absolute;bottom:0;transform:translateX(-50%);font-size:10px;color:#7d8791;white-space:nowrap}.g-row{display:grid;grid-template-columns:350px 1fr 250px;min-height:58px;border-bottom:1px solid #edf0f2;align-items:stretch}.g-row.level-control{background:#fbfcfd}.g-row.level-detail{background:#fff}.g-row.level-rss{background:#fff}.g-row.level-task{min-height:38px;background:#fff}.g-label{padding:8px 8px 6px 4px;overflow:hidden}.clickable{cursor:pointer}.g-title{font-size:12px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.level-detail .g-title{font-weight:600;padding-left:18px}.level-rss .g-title{font-weight:500;padding-left:34px;font-size:11px}.level-task .g-title{font-weight:400;padding-left:52px;font-size:11px;color:#555f69}.chev{display:inline-block;width:14px;color:#7b858f}.g-sub{font-size:10px;color:#7b858f;margin:3px 0 0 14px}.g-lanes{position:relative;padding:5px 0;background-image:linear-gradient(to right,#f3f4f6 1px,transparent 1px);background-size:8.333% 100%}.lane{position:relative;height:20px;margin:2px 0}.lane-label{position:absolute;left:3px;top:2px;font-size:9px;color:#8a939c;z-index:4}.work-plan{position:absolute;top:5px;height:10px;background:#b9c2cc;border-radius:2px}.work-fact{position:absolute;top:8px;height:4px;background:#315d85;border-radius:2px}.forecast-mark{position:absolute;top:2px;height:16px;width:2px;background:#b42318}.cut-mark{position:absolute;top:0;bottom:0;width:1px;background:#111820;opacity:.32}.paybar{position:absolute;bottom:2px;width:4px;transform:translateX(-3px);border-radius:1px 1px 0 0}.pay-plan{background:#c7cdd3}.pay-fact{background:#242e38;transform:translateX(2px)}.g-metrics{padding:7px 4px 5px 10px;font-size:10px;line-height:1.45;color:#4f5963}.metric-main{font-size:11px;font-weight:600}.metric-money{margin-top:3px;color:#68727d}.detail-hint{font-size:11px;color:#68727d;margin-bottom:8px}#loginBox{display:none}
</style></head><body>
<header><h1>DevelopAid · Project Monitor</h1><span class="ver">__VERSION__</span></header><main>
<div class="card" id="loginBox"><h2>Нужен вход</h2><div class="muted">Используется та же сессия, что в DevelopAid. Если она истекла, откройте основной сервис и войдите снова.</div></div>
<div class="card"><div class="row"><label>Проект <input id="project" value="Гродненская"></label><label>Срез <input id="cut" type="date"></label><button class="dark" id="refresh">Обновить</button><span class="muted" id="source"></span></div><div class="msg" id="viewMsg"></div></div>
<div class="card setup"><h2>1. Baseline проекта <span class="pill">один раз</span></h2><div class="muted section-note">Лучше загружать DevelopAid Project Control: из него берутся PM/ГПР, RSS-мэппинг и фиксированный план оплат. Baseline не меняется от недельных срезов.</div><div class="row"><input type="file" id="baselineFile" accept=".xlsx"><label>дата baseline <input id="baselineDate" type="date"></label><button id="baselineBtn">Создать baseline</button><span class="muted" id="baselineState"></span></div><div class="msg" id="baselineMsg"></div></div>
<div class="card weekly"><h2>2. Еженедельное обновление <span class="pill">только РСС 6.1.2</span></h2><div class="muted section-note">Физический факт — только «Реестр выполненных работ». Денежный факт — только «Реестр платежей» того же файла.</div><div class="row"><input type="file" id="rssFile" accept=".xlsx"><label>дата среза <input id="rssDate" type="date"></label><button class="dark" id="rssBtn">Загрузить РСС и пересчитать</button><span class="muted" id="rssHistory"></span></div><div class="msg" id="rssMsg"></div></div>
<div class="card" id="summaryCard" style="display:none"><h2>Свод</h2><div class="grid" id="summary"></div></div>
<div class="card" id="ganttCard" style="display:none"><h2>Управленческий Гант · работы + оплаты</h2><div class="detail-hint">По умолчанию показан верхний уровень. Нажмите на строку, чтобы раскрыть DevelopAid → RSS → WBS. Сортировка идёт по номеру RSS-статьи.</div><div class="legend"><span class="lg"><i class="sw"></i>baseline работ</span><span class="lg"><i class="sw fact"></i>факт работ из актов</span><span class="lg"><i class="sw forecast"></i>прогноз окончания</span><span class="lg"><i class="sw payplan"></i>план оплат</span><span class="lg"><i class="sw payfact"></i>факт оплат</span></div><div class="scroll"><div class="gantt-wrap" id="gantt"></div></div></div>
<div class="card" id="cashCard" style="display:none"><h2>Оплаты · помесячно по проекту</h2><div class="muted section-note" id="cashNote"></div><div class="scroll"><table id="cash"></table></div></div>
<div class="card" id="trendCard" style="display:none"><h2>История недельных срезов РСС</h2><div class="scroll"><table id="trend"></table></div></div>
</main><script>
'use strict';
const $=id=>document.getElementById(id),SESSION='developaid_web_session',ADMIN='plato_projects_key';
const expanded=new Set();let lastView=null;
const sess=()=>{try{return localStorage.getItem(SESSION)||''}catch(e){return''}},key=()=>{try{return localStorage.getItem(ADMIN)||''}catch(e){return''}};
const today=()=>new Date().toISOString().slice(0,10),money=v=>v==null?'—':(Number(v)/1e6).toLocaleString('ru-RU',{maximumFractionDigits:1})+' млн ₽',pct=v=>v==null?'—':(Number(v)*100).toLocaleString('ru-RU',{maximumFractionDigits:1})+'%',date=v=>v?String(v).slice(0,10):'—';
$('cut').value=$('rssDate').value=$('baselineDate').value=today();
async function post(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.assign({session:sess(),key:key()},body||{}))});const d=await r.json().catch(()=>({}));if(r.status===401)$('loginBox').style.display='';if(!r.ok)throw new Error(d.detail||('HTTP '+r.status));return d}
async function get(path,p){const q=new URLSearchParams(Object.assign({session:sess(),key:key()},p||{})),r=await fetch(path+'?'+q),d=await r.json().catch(()=>({}));if(r.status===401)$('loginBox').style.display='';if(!r.ok)throw new Error(d.detail||('HTTP '+r.status));return d}
const b64=f=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(f)});
function msg(id,text,good=false){const e=$(id);e.textContent=text;e.className='msg '+(good?'ok':'err')}
function kpi(label,value,cls=''){return `<div class="kpi"><div class="l">${label}</div><div class="n ${cls}">${value}</div></div>`}
function statusClass(s){return s==='В СРОК'||s==='ЗАВЕРШЕНО'?'status-good':(s==='ОТСТАВАНИЕ'||s==='НЕТ ТЕМПА / РИСК'?'status-bad':'status-muted')}
async function loadSnapshots(){const p=$('project').value.trim();if(!p)return;try{const s=await get('/monitor/snapshots',{project:p});$('baselineState').textContent=s.baseline&&s.baseline.length?'Baseline создан':'Baseline ещё не создан';$('rssHistory').textContent=(s.estimate||[]).length?`${s.estimate.length} срез(ов): ${(s.estimate||[]).join(', ')}`:'Срезов РСС пока нет'}catch(e){}}
$('baselineBtn').onclick=async()=>{const f=$('baselineFile').files[0],p=$('project').value.trim();if(!f)return msg('baselineMsg','Выберите baseline-файл');try{msg('baselineMsg','Загружаю…',true);const d=await post('/monitor/schedule',{project:p,taken_at:$('baselineDate').value,gpr_base64:await b64(f),pm_base64:''});msg('baselineMsg',`Baseline создан: ${d.works||'—'} работ${d.payment_plan?' · план оплат найден':' · план оплат не найден'}`,true);await loadSnapshots();await refresh()}catch(e){msg('baselineMsg',e.message)}};
$('rssBtn').onclick=async()=>{const f=$('rssFile').files[0],p=$('project').value.trim(),d=$('rssDate').value;if(!f)return msg('rssMsg','Выберите свежую 6.1.2');try{msg('rssMsg','Читаю акты и платежи…',true);await post('/monitor/estimate',{project:p,taken_at:d,filename:f.name,content_base64:await b64(f)});$('cut').value=d;msg('rssMsg','Срез сохранён. Работы и оплаты пересчитаны.',true);await loadSnapshots();await refresh()}catch(e){msg('rssMsg',e.message)}};
$('refresh').onclick=()=>refresh();$('project').onchange=()=>loadSnapshots();
function renderSummary(v){const s=v.schedule||{},m=v.money||{},p=v.payments||{},mg=s.management||[];const risk=mg.filter(x=>x.status==='ОТСТАВАНИЕ'||x.status==='НЕТ ТЕМПА / РИСК').length;$('summaryCard').style.display='';$('summary').innerHTML=kpi('Baseline конец',date(s.baseline_end))+kpi('Прогноз конца',date(s.forecast_end),s.forecast_end&&s.baseline_end&&s.forecast_end>s.baseline_end?'bad':'good')+kpi('Рисковых блоков',String(risk),risk?'bad':'good')+kpi('Физический факт',money(m.accepted))+kpi('Оплачено',money(m.payment_fact))+kpi('План оплат',p.known?money(p.plan_total):'нет baseline')}
function renderCash(v){const p=v.payments||{},rows=p.rows||[];$('cashCard').style.display='';$('cashNote').textContent=p.known?'План — фиксированный baseline; факт — «Реестр платежей» текущего РСС.':'Факт оплат есть, но в baseline не найден «CF ПЛАН-ФАКТ».';$('cash').innerHTML='<tr><th>Месяц</th><th>План</th><th>Факт</th><th>Δ</th></tr>'+rows.map(r=>`<tr><td>${r.month.slice(0,7)}</td><td>${money(r.plan)}</td><td>${money(r.fact)}</td><td class="${r.delta!=null&&r.delta>0?'bad':''}">${money(r.delta)}</td></tr>`).join('')}
function renderTrend(t){$('trendCard').style.display=t.length?'':'none';if(!t.length)return;$('trend').innerHTML='<tr><th>Срез</th><th>Выполнено по актам</th><th>Оплачено</th><th>Рисков</th><th>Прогноз конца</th></tr>'+t.map(r=>`<tr><td>${r.snapshot}</td><td>${money(r.accepted)}</td><td>${money(r.payment_fact||r.paid)}</td><td>${r.risks==null?'—':r.risks}</td><td>${date(r.forecast_end)}</td></tr>`).join('')}
function visibleRows(nodes,depth=0,out=[]){for(const n of nodes||[]){out.push({node:n,depth});if(expanded.has(n.key)&&n.children&&n.children.length){if(n.level==='rss'){for(const t of n.children)out.push({node:Object.assign({key:'task:'+String(t.id||t.wbs),level:'task'},t),depth:depth+1})}else visibleRows(n.children,depth+1,out)}}return out}
function monthEntries(obj){return Object.entries(obj||{}).sort((a,b)=>a[0].localeCompare(b[0]))}
function controlCode(name){return {'Подготовка':'2.1','Основные объекты':'2.2','Наружные сети':'2.4','Благоустройство':'2.5','Служба заказчика':'2.6','Проектирование':'2.7'}[name]||''}
function renderGantt(v){const roots=(v.schedule||{}).management||[];if(!roots.length){$('ganttCard').style.display='none';return}$('ganttCard').style.display='';const flat=visibleRows(roots);const dates=[];for(const {node:n} of flat){if(n.plan_start)dates.push(new Date(n.plan_start));if(n.plan_finish)dates.push(new Date(n.plan_finish));if(n.forecast_finish)dates.push(new Date(n.forecast_finish));const p=n.payments||{};for(const [m] of [...monthEntries(p.plan),...monthEntries(p.fact)])dates.push(new Date(m))}dates.push(new Date(v.cut));let min=new Date(Math.min(...dates)),max=new Date(Math.max(...dates));min=new Date(min.getFullYear(),min.getMonth(),1);max=new Date(max.getFullYear(),max.getMonth()+1,1);if(!(max>min))max=new Date(min.getTime()+86400000);const span=max-min,pos=d=>Math.max(0,Math.min(100,(new Date(d)-min)/span*100)),cutPos=pos(v.cut);let ticks='';let tm=new Date(min);let ix=0;while(tm<=max){if(ix%3===0)ticks+=`<span class="tick" style="left:${pos(tm.toISOString())}%">${tm.toLocaleDateString('ru-RU',{month:'short',year:'2-digit'})}</span>`;tm=new Date(tm.getFullYear(),tm.getMonth()+1,1);ix++}let h=`<div class="g-axis"><div class="muted">Статья / работа</div><div class="axis-time">${ticks}</div><div class="muted">План / факт / деньги</div></div>`;for(const {node:n} of flat){const level=n.level||'task',hasKids=level!=='task'&&n.children&&n.children.length,open=expanded.has(n.key);const l=n.plan_start?pos(n.plan_start):0,w=n.plan_start&&n.plan_finish?Math.max(.3,pos(n.plan_finish)-l):0,fw=n.plan_start&&n.actual_equivalent_date?Math.max(0,pos(n.actual_equivalent_date)-l):0,fp=n.forecast_finish?pos(n.forecast_finish):null,pay=n.payments||{},plans=monthEntries(pay.plan),facts=monthEntries(pay.fact),mx=Math.max(1,...plans.map(x=>Number(x[1])||0),...facts.map(x=>Number(x[1])||0));let bars='';for(const [m,val] of plans){bars+=`<i class="paybar pay-plan" style="left:${pos(m)}%;height:${Math.max(2,14*(Number(val)||0)/mx)}px" title="План ${m.slice(0,7)}: ${money(val)}"></i>`}for(const [m,val] of facts){bars+=`<i class="paybar pay-fact" style="left:${pos(m)}%;height:${Math.max(2,14*(Number(val)||0)/mx)}px" title="Факт ${m.slice(0,7)}: ${money(val)}"></i>`}const prefix=level==='control'?controlCode(n.name):(level==='rss'?(n.code||''):'');const title=(prefix?prefix+' · ':'')+(n.name||n.wbs||'');const payText=pay.plan_total!=null?`Оплаты ${money(pay.fact_total||0)} / план ${money(pay.plan_total)}`:(pay.fact_total?`Оплачено ${money(pay.fact_total)}`:'');h+=`<div class="g-row level-${level}"><div class="g-label ${hasKids?'clickable':''}" data-key="${n.key||''}"><div class="g-title ${statusClass(n.status)}"><span class="chev">${hasKids?(open?'▾':'▸'):''}</span>${title}</div><div class="g-sub">${n.status||''}</div></div><div class="g-lanes"><div class="lane"><span class="lane-label">работы</span><i class="cut-mark" style="left:${cutPos}%"></i>${w?`<i class="work-plan" style="left:${l}%;width:${w}%"></i>`:''}${fw?`<i class="work-fact" style="left:${l}%;width:${fw}%"></i>`:''}${fp!=null?`<i class="forecast-mark" style="left:${fp}%"></i>`:''}</div><div class="lane"><span class="lane-label">оплаты</span><i class="cut-mark" style="left:${cutPos}%"></i>${bars}</div></div><div class="g-metrics"><div class="metric-main">План ${pct(n.plan_progress)} · факт ${pct(n.actual_progress)}</div><div>Прогноз ${date(n.forecast_finish)}${n.delta_days!=null?' · Δ '+n.delta_days+' дн.':''}</div><div class="metric-money">${payText}</div></div></div>`}$('gantt').innerHTML=h;document.querySelectorAll('.g-label.clickable').forEach(el=>el.onclick=()=>{const k=el.dataset.key;if(expanded.has(k))expanded.delete(k);else expanded.add(k);renderGantt(lastView)})}
async function refresh(){const p=$('project').value.trim(),cut=$('cut').value;if(!p||!cut)return;msg('viewMsg','');try{const d=await post('/monitor/view',{project:p,cut:cut,upto:''});const v=d.snapshot||d.view||d.report||d,t=d.trend||[];lastView=v;$('source').textContent=`РСС: ${(v.source||{}).estimate||'—'} · физика: Реестр выполненных работ · деньги: Реестр платежей`;renderSummary(v);renderCash(v);renderGantt(v);renderTrend(t)}catch(e){['summaryCard','ganttCard','cashCard','trendCard'].forEach(id=>$(id).style.display='none');msg('viewMsg',e.message)}}
loadSnapshots().then(refresh);
</script></body></html>"""
